"""Shared fixtures. All data is synthetic: a tone generated by ffmpeg."""

from __future__ import annotations

import os
import shutil
import signal
import subprocess
from collections.abc import Iterator
from pathlib import Path

import pytest

requires_ffmpeg = pytest.mark.skipif(
    shutil.which("ffmpeg") is None or shutil.which("ffprobe") is None,
    reason="requires ffmpeg and ffprobe",
)


@pytest.fixture
def sine_audio(tmp_path: Path) -> Path:
    """Two seconds of a sine wave as mp3."""
    path = tmp_path / "tone.mp3"
    subprocess.run(
        [
            "ffmpeg",
            "-y",
            "-v",
            "error",
            "-f",
            "lavfi",
            "-i",
            "sine=frequency=440:duration=2",
            str(path),
        ],
        check=True,
    )
    return path


@pytest.fixture(autouse=True)
def _restore_environ(monkeypatch: pytest.MonkeyPatch) -> None:
    """`cli.main` sets offline variables in `os.environ`; none remain after the test."""
    from transcribator.i18n import RECORDING_LANG_ENV, UI_LANG_ENV  # noqa: PLC0415
    from transcribator.offline import DOWNLOAD_ENV, OFFLINE_ENV  # noqa: PLC0415

    # The user's shell may set languages: every test starts from the defaults (English).
    for key in {*OFFLINE_ENV, *DOWNLOAD_ENV, UI_LANG_ENV, RECORDING_LANG_ENV}:
        monkeypatch.delenv(key, raising=False)


@pytest.fixture(autouse=True)
def _restore_process_state() -> Iterator[None]:
    """`cli.main` sets umask and SIGTERM/SIGHUP handlers for the whole pytest process."""
    handlers = {sig: signal.getsignal(sig) for sig in (signal.SIGTERM, signal.SIGHUP)}
    umask = os.umask(0o022)
    os.umask(umask)
    yield
    os.umask(umask)
    for sig, handler in handlers.items():
        signal.signal(sig, handler)
